import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Design Mode","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/design-mode.md","filePath":"zh/products/ai-coding/cursor/design-mode.md","lastUpdated":1787107158000}'),d={name:"zh/products/ai-coding/cursor/design-mode.md"};function n(s,t,i,l,h,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="design-mode" tabindex="-1">Design Mode <a class="header-anchor" href="#design-mode" aria-label="Permalink to &quot;Design Mode&quot;">​</a></h1><p>Design Mode 让你用<strong>视觉提示</strong>指挥 Agent。在 <a href="https://cursor.com/docs/agent/agents-window" target="_blank" rel="noreferrer">Agents Window</a> 的浏览器里，点元素、在页面上画、或开口说。Cursor 会带上元素和截图去改代码，你继续看下一处。</p><blockquote><p>官方：<a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>。开关：<strong><code>Cmd+Shift+D</code></strong>。</p><p>这是<strong>应用内的 UI 指挥</strong>，不是独立设计画布。本站近亲：<a href="./../claude/claude-design.html">Claude Design</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>Cursor 桌面端，<strong>Agents Window</strong> 浏览器已打开正在跑的应用</li><li>那个浏览器里能真正加载 UI（本地 dev server 或预览）</li><li>一个擅长界面、够快的模型 — 官方推荐：<strong><a href="https://cursor.com/blog/composer-2-5" target="_blank" rel="noreferrer">Composer 2.5</a></strong></li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本页你能：</p><ol><li>不离开正在跑的应用，打开 / 关掉 Design Mode</li><li>对准一个元素、多个元素、画出来的区域，或一段语音</li><li>知道 Agent 实际看到什么（身份 + 截图）</li><li>第一个改动还没完，就能排上下一个视觉编辑</li></ol><hr><h2 id="为什么要用视觉提示" tabindex="-1">为什么要用视觉提示 <a class="header-anchor" href="#为什么要用视觉提示" aria-label="Permalink to &quot;为什么要用视觉提示&quot;">​</a></h2><p>UI 是空间的。「把 hero 不那么挤」不如：选中的节点、背后的代码、周围布局、以及你正在看的页面状态。</p><p>在运行中的应用里点一个元素，对着这个选区下指令，让 Agent 改源码。</p><h2 id="打开-design-mode" tabindex="-1">打开 Design Mode <a class="header-anchor" href="#打开-design-mode" aria-label="Permalink to &quot;打开 Design Mode&quot;">​</a></h2><p>Design Mode 住在 <strong>Agents Window 里的浏览器</strong>。</p><ol><li>打开 Agents Window 浏览器</li><li><strong><code>Cmd+Shift+D</code></strong> 打开 Design Mode</li><li>同一快捷键关掉，回到普通浏览</li></ol><h2 id="怎么指挥-agent" tabindex="-1">怎么指挥 Agent <a class="header-anchor" href="#怎么指挥-agent" aria-label="Permalink to &quot;怎么指挥 Agent&quot;">​</a></h2><h3 id="选一个元素" tabindex="-1">选一个元素 <a class="header-anchor" href="#选一个元素" aria-label="Permalink to &quot;选一个元素&quot;">​</a></h3><p>在运行中的产品上点任意元素。Agent 拿到元素<strong>和</strong>它的代码，你对着看见的东西说话。</p><h3 id="选多个元素" tabindex="-1">选多个元素 <a class="header-anchor" href="#选多个元素" aria-label="Permalink to &quot;选多个元素&quot;">​</a></h3><p>改动取决于<strong>关系</strong>时用多选：让 A 对齐 B、去掉重复内容、或一组一起调。</p><h3 id="在页面上画" tabindex="-1">在页面上画 <a class="header-anchor" href="#在页面上画" aria-label="Permalink to &quot;在页面上画&quot;">​</a></h3><p>圈一块挤的区域、框一块、或标动画页的一部分。标注叠在视口的<strong>冻结帧</strong>上，Agent 看到的是你当时响应的那一屏。</p><h3 id="用语音说" tabindex="-1">用语音说 <a class="header-anchor" href="#用语音说" aria-label="Permalink to &quot;用语音说&quot;">​</a></h3><p>不打字，开口说。Agent 还在跑时麦克风仍可用，你可以接着排下一处。语音和画可以一起用。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><p>官方表：</p><table tabindex="0"><thead><tr><th>动作</th><th>快捷键</th></tr></thead><tbody><tr><td>开关 Design Mode</td><td><code>Cmd+Shift+D</code></td></tr><tr><td>框选区域</td><td><code>Shift+drag</code></td></tr><tr><td>把元素加进 chat</td><td><code>Cmd+L</code></td></tr><tr><td>把元素加进输入框</td><td><code>Option+click</code></td></tr></tbody></table><h2 id="agent-看到什么" tabindex="-1">Agent 看到什么 <a class="header-anchor" href="#agent-看到什么" aria-label="Permalink to &quot;Agent 看到什么&quot;">​</a></h2><p>选中元素会补上两路信号：</p><table tabindex="0"><thead><tr><th>信号</th><th>内容</th><th>为什么</th></tr></thead><tbody><tr><td><strong>元素身份</strong></td><td>xpath、组件、属性、计算样式、<strong>fiber tree</strong> 上的 props</td><td>找到源码，改对文件</td></tr><tr><td><strong>截图</strong></td><td>布局、周围元素、当时的页面状态</td><td>空间上下文</td></tr></tbody></table><p>官方没写的东西（整棵 DOM、HAR、设计 token）不要编进去。</p><h2 id="连续改" tabindex="-1">连续改 <a class="header-anchor" href="#连续改" aria-label="Permalink to &quot;连续改&quot;">​</a></h2><p>一处 UI 改完通常立刻看到下一处。点一个元素、说清改动、挪到页面另一边，在<strong>第一处还没跑完</strong>时就发出下一处。Agent 完成后应用会热更新。</p><p>这就是在界面上同时管多个 <strong>subagents</strong> 的方式。</p><p>iOS 应用也能进 Design Mode（对照片或前端组件点选、涂画）。那在 <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Cursor for iOS</a> — 本页只讲桌面 Agents Window。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><ul><li>正在跑的页面上调间距、对齐、「让这个长得像那个」</li><li>挤或在动的区域，画比写更快</li><li>手忙：上一个 Agent 还在跑，用语音排下一个</li></ul><p>不是视觉问题（API 契约、数据模型）就回普通 Agent 对话。需要<strong>独立</strong>、跟品牌走的画布和 handoff 包时，用 <a href="./../claude/claude-design.html">Claude Design</a>，不是编辑器里的这层叠加。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>像素级改动只靠文字</td><td>选中元素或画出区域</td></tr><tr><td>忘了它住在 Agents Window <strong>浏览器</strong></td><td>先开那个浏览器，再 <code>Cmd+Shift+D</code></td></tr><tr><td>选了慢、不擅长 UI 的模型</td><td>官方：<strong>Composer 2.5</strong></td></tr><tr><td>以为涂鸦会跟着动画走</td><td>标注在<strong>冻结</strong>视口帧上</td></tr><tr><td>和 Claude Design 搞混</td><td>Claude Design 是独立 Web 画布；这是对着<strong>正在跑的应用</strong>做视觉提示</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cursor.html">Cursor 教程</a> — 编辑器里的 Agent / Ask / Plan / Debug</li><li><a href="./cloud-agents.html">Cloud Agents</a> — 同一家族，隔离 VM</li><li>官方：<a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>、<a href="https://cursor.com/docs/agent/agents-window" target="_blank" rel="noreferrer">Agents Window</a>、<a href="https://cursor.com/docs/agent/tools/browser" target="_blank" rel="noreferrer">Browser</a></li></ul>',42)])])}const f=e(d,[["render",n]]);export{m as __pageData,f as default};
